7	/**
8	 * On create, records how many existing owners already share this owner's first and last name
9	 * (compared case-insensitively) as {@code namesakeCount}. Runs before {@code SaveOwner} so the
10	 * not-yet-persisted owner is excluded from the count.
11	 */
12	public class AssignOwnerNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        int count = 0;
16	        for (Owner existing : ownerRepository.findAll()) {
17	            if (namesake(existing.getFirstName(), owner.getFirstName())
18	                    && namesake(existing.getLastName(), owner.getLastName())) {
19	                count++;
20	            }
21	        }
22	        owner.setNamesakeCount(count);
23	    }
24	
25	    private static boolean namesake(String a, String b) {
26	        return a == null ? b == null : a.equalsIgnoreCase(b);
27	    }
28	}
